"""Vehicle trajectories, generated by exact integration of a unicycle model.

A constant twist, meaning a constant forward speed and a constant yaw rate, has a
closed form solution: the vehicle follows a circular arc of radius ``v / omega``.
Integrating it exactly rather than by an Euler step keeps the trajectory independent
of the sampling interval, so halving the step count does not move the path. The
integration tests rely on that: they run the examples at a reduced step count and
still traverse the same route.

The step is written as a body-frame displacement composed onto the current pose, which
is the exponential map of SE(2) applied to the twist. Writing it that way keeps the
arithmetic in one place: the rotation lives in
:func:`freespace_grid.model.transform.compose` and this module supplies only the
displacement.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

from freespace_grid.model.transform import Pose2D, compose

__all__ = ["Trajectory", "constant_twist", "from_segments"]


@dataclass(frozen=True, slots=True)
class Trajectory:
    """A time-stamped sequence of poses."""

    poses: tuple[Pose2D, ...]
    times: tuple[float, ...]

    def __post_init__(self) -> None:
        if len(self.poses) != len(self.times):
            raise ValueError(
                "poses and times must have equal length, got "
                f"{len(self.poses)} and {len(self.times)}"
            )
        if not self.poses:
            raise ValueError("a trajectory needs at least one pose")

    def __len__(self) -> int:
        return len(self.poses)

    @property
    def duration(self) -> float:
        """Elapsed time between the first and last pose, in seconds."""
        return self.times[-1] - self.times[0]

    def subsample(self, count: int) -> Trajectory:
        """Return at most ``count`` poses spread evenly over the trajectory.

        The first and last pose are always kept, so the route and the elapsed time are
        preserved while the number of scans falls. This is how the integration tests
        shorten a run without changing what it covers.
        """
        if count < 1:
            raise ValueError(f"count must be at least one, got {count}")
        total = len(self.poses)
        if count >= total:
            return self
        if count == 1:
            return Trajectory(poses=(self.poses[0],), times=(self.times[0],))
        picks = [round(i * (total - 1) / (count - 1)) for i in range(count)]
        return Trajectory(
            poses=tuple(self.poses[i] for i in picks),
            times=tuple(self.times[i] for i in picks),
        )


def _body_step(speed: float, yaw_rate: float, dt: float) -> Pose2D:
    """Body-frame displacement produced by one interval of a constant twist.

    For a zero yaw rate this is a straight advance. Otherwise the vehicle traces an arc
    of radius ``speed / yaw_rate``, and the chord written in the starting body frame is
    ``(r sin(omega dt), r (1 - cos(omega dt)))`` with a heading change of ``omega dt``.
    """
    if abs(yaw_rate) < 1e-12:
        return Pose2D(x=speed * dt, y=0.0, theta=0.0)
    radius = speed / yaw_rate
    turn = yaw_rate * dt
    return Pose2D(
        x=radius * math.sin(turn),
        y=radius * (1.0 - math.cos(turn)),
        theta=turn,
    )


def _advance(pose: Pose2D, speed: float, yaw_rate: float, dt: float) -> Pose2D:
    """Exact unicycle update over one interval."""
    return compose(pose, _body_step(speed, yaw_rate, dt))


def constant_twist(
    start: Pose2D, speed: float, yaw_rate: float, dt: float, steps: int
) -> Trajectory:
    """Return ``steps + 1`` poses along a constant twist starting at ``start``."""
    if steps < 0:
        raise ValueError(f"steps must not be negative, got {steps}")
    if dt <= 0.0:
        raise ValueError(f"dt must be positive, got {dt}")
    poses = [start.normalized()]
    times = [0.0]
    for index in range(steps):
        poses.append(_advance(poses[-1], speed, yaw_rate, dt))
        times.append((index + 1) * dt)
    return Trajectory(poses=tuple(poses), times=tuple(times))


def from_segments(
    start: Pose2D, segments: tuple[tuple[float, float, int], ...], dt: float
) -> Trajectory:
    """Chain constant twist segments given as ``(speed, yaw_rate, steps)`` triples."""
    poses = [start.normalized()]
    times = [0.0]
    for speed, yaw_rate, steps in segments:
        for _ in range(steps):
            poses.append(_advance(poses[-1], speed, yaw_rate, dt))
            times.append(times[-1] + dt)
    return Trajectory(poses=tuple(poses), times=tuple(times))
